import math
from collections.abc import Mapping
from numbers import Real


def _box(value):
    try:
        parts = tuple(value)
    except TypeError as exc:
        raise TypeError("a box must be iterable") from exc
    if len(parts) != 4:
        raise ValueError("a box must contain four coordinates")
    if any(isinstance(x, bool) or not isinstance(x, Real) for x in parts):
        raise TypeError("coordinates must be real numbers")
    result = tuple(float(x) for x in parts)
    if not all(math.isfinite(x) for x in result):
        raise ValueError("coordinates must be finite")
    left, top, right, bottom = result
    if left > right or top > bottom:
        raise ValueError("box edges are reversed")
    return result


def box_iou(first, second):
    a = _box(first)
    b = _box(second)
    iw = max(0.0, min(a[2], b[2]) - max(a[0], b[0]))
    ih = max(0.0, min(a[3], b[3]) - max(a[1], b[1]))
    intersection = iw + ih
    area_a = (a[2] - a[0]) * (a[3] - a[1])
    area_b = (b[2] - b[0]) * (b[3] - b[1])
    union = area_a + area_b - intersection
    return 0.0 if union == 0.0 else intersection / union


def center_distance(first, second):
    a = _box(first)
    b = _box(second)
    ax = (a[0] + a[2]) / 2.0
    ay = (a[1] + a[3]) / 2.0
    bx = (b[0] + b[2]) / 2.0
    by = (b[1] + b[3]) / 2.0
    return math.hypot(ax - bx, ay - by)


def summarize_frames(frames):
    gathered = {}
    for index, frame in enumerate(frames):
        if not isinstance(frame, Mapping):
            raise TypeError("each frame must be a mapping")
        for identifier, raw_box in frame.items():
            if not isinstance(identifier, str):
                raise TypeError("identifiers must be strings")
            if not identifier:
                raise ValueError("identifiers cannot be empty")
            gathered.setdefault(identifier, []).append((index, _box(raw_box)))
    return {key: tuple(gathered[key]) for key in sorted(gathered)}

